import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount } from './invoices.js';
import { roundCents } from './money.js';

/**
 * Get all overdue invoices as of a given date.
 * @param {Array<{ number: string, status: string, dueDate: string, ...rest }>} invoices - All invoices
 * @param {string} asOf - Date in YYYY-MM-DD format (cutoff date)
 * @returns {Array<{ number: string, customerId: string, dueDate: string, daysOverdue: number, due: number }>} - Sorted by most overdue first
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get VAT summary aggregated by rate.
 * @param {Array<{ status: string, lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }>} invoices
 * @returns {Array<{ rate: number, base: number, vat: number }>} - Sorted by rate high to low
 */
export function vatSummary(invoices) {
  const vatByRate = {};

  invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid' || inv.status === 'paid')
    .forEach((inv) => {
      inv.lines.forEach((line) => {
        const base = lineTotal(line) - lineDiscount(line);
        const vat = roundCents(base * (line.vatRate / 100));
        const rate = line.vatRate;

        if (!vatByRate[rate]) {
          vatByRate[rate] = { rate, base: 0, vat: 0 };
        }
        vatByRate[rate].base += base;
        vatByRate[rate].vat += vat;
      });
    });

  return Object.values(vatByRate).sort((a, b) => b.rate - a.rate);
}

