  const item = result[0];
  assert.equal(item.number, 'INV-2024-0001');
  assert.equal(item.customerId, 'C-002');
  assert.equal(item.dueDate, '2024-02-14');
  assert.equal(item.daysOverdue, 30);
  assert.equal(item.due, 5 * 8500 * 1.21);
});

test('vatSummary returns empty list for no invoices', () => {
  const result = vatSummary([]);
  assert.deepEqual(result, []);
});

test('vatSummary excludes draft invoices', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-01-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  assert.equal(inv.ok, true);
